<script setup>
import {ref,computed,onMounted} from 'vue';import {api} from '../lib/api';
const labels={users:'Usuarios',roles:'Roles',permissions:'Permisos'};const tab=ref('users'),users=ref([]),roles=ref([]),permissions=ref([]),loading=ref(false),error=ref(''),success=ref('');
const user=ref({name:'',email:'',password:''}),role=ref({code:'',name:'',description:''}),permission=ref({code:'',name:'',description:''});
const assignedRoles=ref({}),assignedPermissions=ref({});
async function load(){loading.value=true;error.value='';try{const [u,r,p]=await Promise.all([api.get('/users'),api.get('/roles'),api.get('/permissions')]);users.value=u.data;roles.value=r.data;permissions.value=p.data;assignedRoles.value=Object.fromEntries(users.value.map(x=>[x.id,x.roles.map(y=>y.id)]));assignedPermissions.value=Object.fromEntries(roles.value.map(x=>[x.id,x.permissions.map(y=>y.id)]));}catch(e){error.value=e.message;}finally{loading.value=false;}}
async function act(fn){error.value='';success.value='';try{await fn();success.value='Cambios guardados.';await load();}catch(e){error.value=e.message;}}
const createUser=()=>act(async()=>{await api.post('/users',user.value);user.value={name:'',email:'',password:''};});
const createRole=()=>act(async()=>{await api.post('/roles',role.value);role.value={code:'',name:'',description:''};});
const createPermission=()=>act(async()=>{await api.post('/permissions',permission.value);permission.value={code:'',name:'',description:''};});
const saveUserRoles=(x)=>act(()=>api.put('/users/'+x.id+'/roles',{role_ids:assignedRoles.value[x.id]}));
const saveRolePermissions=(x)=>act(()=>api.put('/roles/'+x.id+'/permissions',{permission_ids:assignedPermissions.value[x.id]}));
const toggleUser=(x)=>act(()=>api.patch('/users/'+x.id+'/status',{is_active:!x.is_active}));
const toggleRole=(x)=>act(()=>api.patch('/roles/'+x.id,{is_active:!x.is_active}));
const togglePermission=(x)=>act(()=>api.patch('/permissions/'+x.id,{is_active:!x.is_active}));
async function edit(type,x){const label=prompt('Nuevo nombre',x.name);if(label===null||!label.trim())return;const url={users:'/users/',roles:'/roles/',permissions:'/permissions/'}[type]+x.id;const payload={name:label.trim()};if(type==='users'){const email=prompt('Correo electrónico',x.email);if(email===null)return;const password=prompt('Nueva contraseña (en blanco para conservar la actual)','');if(password===null)return;payload.email=email.trim();if(password.trim())payload.password=password;}await act(()=>api.patch(url,payload));}
onMounted(load);
</script><template><div class="heading"><div><p class="eyebrow">CONTROL DE ACCESO · ACL</p><h1>Administración</h1><p class="sub">Usuarios, roles y permisos; los cambios se validan también en Laravel.</p></div></div><div class="tabs"><button v-for="t in ['users','roles','permissions']" :key="t" class="tab" :class="{active:tab===t}" @click="tab=t">{{labels[t]}}</button></div><p class="alert" v-if="error">{{error}}</p><p class="success" v-if="success">{{success}}</p><p class="state" v-if="loading">Cargando…</p>
<section v-if="tab==='users'" class="panel"><h2>Usuarios</h2><form class="inline-form" @submit.prevent="createUser"><input v-model="user.name" required placeholder="Nombre"/><input v-model="user.email" type="email" required placeholder="Email"/><input v-model="user.password" type="password" minlength="12" required placeholder="Contraseña (12+)"/><button class="btn primary">Crear</button></form><div class="admin-record" v-for="u in users" :key="u.id"><div><strong>{{u.name}}</strong><small>{{u.email}} · {{u.is_active?'Activo':'Inactivo'}}</small></div><div class="checks"><label v-for="r in roles" :key="r.id"><input type="checkbox" :value="r.id" v-model="assignedRoles[u.id]"/>{{r.code}}</label></div><div class="actions"><button class="btn small" @click="saveUserRoles(u)">Guardar roles</button><button class="btn small muted" @click="edit('users',u)">Editar</button><button class="btn small muted" @click="toggleUser(u)">{{u.is_active?'Desactivar':'Activar'}}</button></div></div></section>
<section v-if="tab==='roles'" class="panel"><h2>Roles</h2><form class="inline-form" @submit.prevent="createRole"><input v-model="role.code" required placeholder="Código único"/><input v-model="role.name" required placeholder="Nombre"/><input v-model="role.description" placeholder="Descripción"/><button class="btn primary">Crear</button></form><div class="admin-record" v-for="r in roles" :key="r.id"><div><strong>{{r.name}}</strong><small>{{r.code}} · {{r.is_active?'Activo':'Inactivo'}}</small></div><div class="checks"><label v-for="p in permissions" :key="p.id"><input type="checkbox" :value="p.id" v-model="assignedPermissions[r.id]"/>{{p.code}}</label></div><div class="actions"><button class="btn small" @click="saveRolePermissions(r)">Guardar permisos</button><button class="btn small muted" @click="edit('roles',r)">Editar</button><button class="btn small muted" @click="toggleRole(r)">{{r.is_active?'Desactivar':'Activar'}}</button></div></div></section>
<section v-if="tab==='permissions'" class="panel"><h2>Permisos</h2><form class="inline-form" @submit.prevent="createPermission"><input v-model="permission.code" required placeholder="Código (ej. report.read)"/><input v-model="permission.name" required placeholder="Nombre"/><input v-model="permission.description" placeholder="Descripción"/><button class="btn primary">Crear</button></form><p class="tip">Los permisos personalizados no autorizan endpoints nuevos automáticamente.</p><div class="admin-record" v-for="p in permissions" :key="p.id"><div><strong>{{p.name}}</strong><small>{{p.code}} {{p.is_system?'· Sistema':''}} · {{p.is_active?'Activo':'Inactivo'}}</small></div><div class="actions"><button class="btn small muted" @click="edit('permissions',p)">Editar nombre</button><button v-if="!p.is_system" class="btn small muted" @click="togglePermission(p)">{{p.is_active?'Desactivar':'Activar'}}</button></div></div></section></template>
